@RunWith(MockitoJUnitRunner.class)
public class GalileoProtocolDecoderTest {

    @Mock
    private BaseProtocolDecoder baseProtocolDecoder;

    @Test
    public void constructor_NoExceptions() {
        // Arrange
        Protocol protocol = new Protocol();

        // Act
        GalileoProtocolDecoder galileoProtocolDecoder = new GalileoProtocolDecoder(protocol);

        // Assert
        assert galileoProtocolDecoder != null;
    }

    @Test
    public void decode_ChannelNotSupported_ThrowsException() {
        // Arrange
        Channel channel = mock(Channel.class);
        SocketAddress remoteAddress = mock(SocketAddress.class);
        Object msg = "test";

        when(channel.isSupported(any())).thenReturn(false);

        // Act and Assert
        Exception exception = assertThrows(Exception.class, () -> galileoProtocolDecoder.decode(channel, remoteAddress, msg));
    }

    @Test
    public void decode_NoData_ThrowsException() {
        // Arrange
        Channel channel = mock(Channel.class);
        SocketAddress remoteAddress = mock(SocketAddress.class);
        Object[] data = new Object[0];
        Object msg = "test";

        when(channel.decode(any(), any())).thenReturn(data);

        // Act and Assert
        Exception exception = assertThrows(Exception.class, () -> galileoProtocolDecoder.decode(channel, remoteAddress, msg));
    }

    @Test
    public void decode_DataNotGalileo_ThrowsException() {
        // Arrange
        Channel channel = mock(Channel.class);
        SocketAddress remoteAddress = mock(SocketAddress.class);
        Object[] data = "not galileo".getBytes();
        Object msg = "test";

        when(channel.decode(any(), any())).thenReturn(data);

        // Act and Assert
        Exception exception = assertThrows(Exception.class, () -> galileoProtocolDecoder.decode(channel, remoteAddress, msg));
    }

    @Test
    public void decode_GalileoData_DecodesCorrectly() {
        // Arrange
        Channel channel = mock(Channel.class);
        SocketAddress remoteAddress = mock(SocketAddress.class);
        Object[] data = "galileo data".getBytes();
        Object msg = "test";

        when(channel.decode(any(), any())).thenReturn(data);

        // Act
        Object result = galileoProtocolDecoder.decode(channel, remoteAddress, msg);

        // Assert
        assertEquals(galileoProtocolDecoder.decode(channel, remoteAddress, msg), result);
    }

    @Test
    public void decode_GalileoDataWithSize_ThrowsException() {
        // Arrange
        Channel channel = mock(Channel.class);
        SocketAddress remoteAddress = mock(SocketAddress.class);
        Object[] data = new Object[]{"galileo data", "another data"};
        Object msg = "test";

        when(channel.decode(any(), any())).thenReturn(data);

        // Act and Assert
        Exception exception = assertThrows(Exception.class, () -> galileoProtocolDecoder.decode(channel, remoteAddress, msg));
    }

}

